INSERT INTO profil_pengacara (user_id, bidang_id, bio, pengalaman_tahun, kota, no_izin) VALUES
(101, 1, 'Spesialis tindak pidana korupsi. Berpraktik selama 14 tahun dan aktif mendampingi klien di Jakarta serta sekitarnya. Siap mendampingi sejak pemeriksaan di kepolisian hingga persidangan.', 14, 'Jakarta', 'ADV-0002'),
(102, 1, 'Spesialis narkotika dan psikotropika. Berpengalaman 9 tahun menangani perkara, dari konsultasi awal hingga pendampingan di pengadilan. Siap mendampingi sejak pemeriksaan di kepolisian hingga persidangan.', 9, 'Bandung', 'ADV-0003'),
(103, 1, 'Spesialis kejahatan siber dan UU ITE. Dikenal teliti dan komunikatif, dengan 11 tahun pengalaman mendampingi individu maupun perusahaan. Siap mendampingi sejak pemeriksaan di kepolisian hingga persidangan.', 11, 'Surabaya', 'ADV-0004'),
(104, 1, 'Spesialis kecelakaan lalu lintas. Memiliki 18 tahun praktik dengan pendekatan yang jelas, cepat, dan hemat biaya bagi klien. Siap mendampingi sejak pemeriksaan di kepolisian hingga persidangan.', 18, 'Medan', 'ADV-0005'),
(105, 1, 'Spesialis penipuan dan penggelapan. Berpraktik selama 8 tahun dan aktif mendampingi klien di Bandar Lampung serta sekitarnya. Siap mendampingi sejak pemeriksaan di kepolisian hingga persidangan.', 8, 'Bandar Lampung', 'ADV-0006'),
(106, 1, 'Spesialis peradilan pidana anak. Berpengalaman 12 tahun menangani perkara, dari konsultasi awal hingga pendampingan di pengadilan. Siap mendampingi sejak pemeriksaan di kepolisian hingga persidangan.', 12, 'Yogyakarta', 'ADV-0007'),
