-- ============================================================
-- Ruang Hukum - Data Contoh untuk Demo (Kelompok 25)
-- SEMUA NAMA, AKUN, DAN ISI KONSULTASI DI SINI FIKTIF.
--
-- Cara pakai: jalankan SETELAH schema.sql.
--   phpMyAdmin > klik database ruang_hukum > tab Import > pilih file ini > Go
-- Isinya: 50 pengacara (semua berpengalaman 7 tahun ke atas, tersebar di 6 bidang),
--         9 klien contoh, konsultasi dengan berbagai status, balasan, dan ulasan.
-- Semua akun memakai kata sandi: Admin123!
--
-- PERHATIAN: file ini MENGHAPUS semua konsultasi, balasan, ulasan, dan semua
-- akun selain tiga akun bawaan (admin, klien, pengacara), lalu mengisinya ulang.
-- Aman dijalankan berulang kali.
-- ============================================================
SET NAMES utf8mb4;
USE ruang_hukum;

-- 1. Bersihkan data tes lama
DELETE FROM ulasan;
DELETE FROM balasan;
DELETE FROM konsultasi;
DELETE FROM profil_pengacara WHERE user_id NOT IN (SELECT id FROM users WHERE email = 'pengacara@ruanghukum.test');
DELETE FROM users WHERE email NOT IN ('admin@ruanghukum.test', 'klien@ruanghukum.test', 'pengacara@ruanghukum.test');

-- 2. Pengacara demo (Sari) dilengkapi
UPDATE profil_pengacara
SET bio = 'Spesialis perkara keluarga dan waris. Berpraktik selama 8 tahun dan aktif mendampingi klien di Bandar Lampung serta sekitarnya. Mengutamakan pendekatan yang tenang dan berpihak pada kepentingan terbaik keluarga.',
    pengalaman_tahun = 8, kota = 'Bandar Lampung'
WHERE user_id = (SELECT id FROM users WHERE email = 'pengacara@ruanghukum.test');


